-- Replace contradictory legacy landing copy with concise links into the structured library.
UPDATE content_records SET
  title = 'Trail of the Saber and GMA',
  summary = 'A concise landing page for the structured Trail of the Saber and Gold Medal of Achievement records.',
  details_json = '{"section":"other","body":["Trail of the Saber is a junior-leadership recognition, while the Gold Medal of Achievement is identified by Royal Rangers USA as its highest achievement award for boys.","The Advancement Library holds the source-backed award summaries. Current official pages and leaders remain the source for qualifications, applications, and award decisions."],"links":[{"label":"Open the Advancement Library","url":"/advancement"},{"label":"Official Trail of the Saber page","url":"https://royalrangers.com/training/junior/tots"},{"label":"Official GMA information","url":"https://royalrangers.com/gma"}]}',
  verified_at = '2026-08-12T00:00:00.000Z', updated_at = '2026-08-12T00:00:00.000Z'
WHERE id = 'page-trail-gma';

UPDATE content_records SET
  title = 'Uniforms and the Ideals of Royal Rangers',
  summary = 'Current official links with original context for uniform choices and the Ideals of Royal Rangers.',
  details_json = '{"section":"other","body":["Royal Rangers USA describes four uniform approaches and gives local outposts flexibility to select an option appropriate to their church and community. Current official guidance should be checked before buying or placing insignia.","The Ideals of Royal Rangers bring together its pledge, character code, readiness motto, Golden Rule, and emblem symbolism. This independent site summarizes their role without reproducing the official wording or artwork."],"links":[{"label":"Official uniform information","url":"https://royalrangers.com/uniforms"},{"label":"Official About Us and Ideals page","url":"https://royalrangers.com/about"}]}',
  verified_at = '2026-08-12T00:00:00.000Z', updated_at = '2026-08-12T00:00:00.000Z'
WHERE id = 'page-uniforms-pledges';

UPDATE content_records SET
  summary = 'An introduction to FCF, its Trail of the Grizzly overview, and its separate handbook listing.',
  details_json = '{"section":"other","body":["Frontiersmen Camping Fellowship is a Royal Rangers program for men and boys centered on frontier-era outdoor skills, fellowship, personal development, and service.","Its Trail of the Grizzly and handbook are represented as structured Advancement Library records. An outpost FCF Activity Status remains a separate three-state fact and is never inferred from this national overview."],"links":[{"label":"Open the Advancement Library","url":"/advancement"},{"label":"Official FCF page","url":"https://royalrangers.com/fcf"}]}',
  verified_at = '2026-08-12T00:00:00.000Z', updated_at = '2026-08-12T00:00:00.000Z'
WHERE id = 'page-fcf';

-- Refresh and add visible primary-source provenance.
UPDATE record_sources SET
  label = 'Royal Rangers USA advancement page',
  url = json_extract((SELECT details_json FROM content_records WHERE content_records.id = record_sources.record_id), '$.officialUrl'),
  verified_at = '2026-08-12T00:00:00.000Z'
WHERE record_id IN ('program-ranger-kids', 'program-discovery', 'program-adventure', 'program-expedition');

DELETE FROM record_sources WHERE record_id IN ('page-trail-gma', 'page-uniforms-pledges', 'page-fcf');
