INSERT INTO record_sources (id, record_id, field_name, label, url, verified_at)
SELECT
  'source-' || id || '-advancement-library',
  id,
  'record',
  CASE
    WHEN json_extract(details_json, '$.subtype') = 'handbook' THEN 'Gospel Publishing House product listing'
    WHEN json_extract(details_json, '$.subtype') = 'merit' THEN 'Royal Rangers USA merit index'
    WHEN id = 'trail-fcf-grizzly' THEN 'Royal Rangers USA FCF'
    WHEN id = 'award-trail-saber' THEN 'Royal Rangers USA Trail of the Saber'
    WHEN id = 'award-gma' THEN 'Royal Rangers USA Gold Medal of Achievement'
    ELSE 'Royal Rangers USA advancement page'
  END,
  json_extract(details_json, '$.officialUrl'),
  '2026-08-12T00:00:00.000Z'
FROM content_records
WHERE kind = 'advancement'
  AND id NOT IN ('program-ranger-kids', 'program-discovery', 'program-adventure', 'program-expedition');

INSERT INTO audit_events (record_id, action, actor, after_json, reason, created_at)
SELECT id, 'advancement library seeded', 'MVP seed', details_json,
  'Slice 2 source-backed advancement and handbook library', '2026-08-12T00:00:00.000Z'
FROM content_records
WHERE kind = 'advancement' OR id IN ('page-trail-gma', 'page-uniforms-pledges', 'page-fcf');
